Future<int> main() async {
  final archive = await PmTilesArchive.from("/path/to/file.pmtiles");
  try {
    print("Type: ${archive.tileType}");
    final int tileId = ZXY(4, 3, 2).toTileId();
    final Tile t = await archive.tile(tileId);
    t.bytes();
  } finally {
    await archive.close();
  }
  return 0;
}
